<?php
require 'db.php'; require_admin();
$counts=[];foreach(['users','students','events','registrations'] as $table){$counts[$table]=(int)$pdo->query("SELECT COUNT(*) FROM `$table`")->fetchColumn();}
$logs=$pdo->query('SELECT a.action,a.details,a.created_at,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 12')->fetchAll();
?>
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Overview</title><style>body{font:15px system-ui;background:#f4f7fb;padding:24px;color:#172033}.wrap{max-width:1050px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.card{background:white;border-radius:14px;padding:20px}.n{font-size:2rem;font-weight:800;color:#3157d5}table{width:100%;border-collapse:collapse;background:white}td,th{padding:10px;text-align:left;border-bottom:1px solid #e4e9f1}a{color:#3157d5}</style><main class="wrap"><p><a href="dashboard.php">← Dashboard</a></p><h1>Admin overview</h1><div class="grid"><?php foreach($counts as $label=>$value):?><section class="card"><h2><?=h(ucfirst($label))?></h2><div class="n"><?=$value?></div></section><?php endforeach;?></div><h2>Recent audit activity</h2><table><tr><th>User</th><th>Action</th><th>Details</th><th>Time</th></tr><?php foreach($logs as $log):?><tr><td><?=h($log['full_name']??'System')?></td><td><?=h($log['action'])?></td><td><?=h($log['details']??'')?></td><td><?=h($log['created_at'])?></td></tr><?php endforeach;?></table><p><a href="students.php">Student management</a> · <a href="events_admin.php">Event management</a> · <a href="logout.php">Logout</a></p></main></html>
